import hash from 'object-hash';
import { v4 as uuidv4 } from 'uuid';
import { getSecuritySchemeNameFromFragment } from '../componentRefs.js';
const SECURITY_SCHEMES_POINTER = '#/components/securitySchemes/';
export const resolveSecuritySchemeName = (key, refUuidMap) => {
    const hasScheme = (name) => Object.prototype.hasOwnProperty.call(refUuidMap, `${SECURITY_SCHEMES_POINTER}${name}`);
    if (hasScheme(key))
        return key;
    const name = getSecuritySchemeNameFromFragment(key);
    if (name === undefined)
        return undefined;
    return hasScheme(name) ? name : undefined;
};
export const mapSecurityRequirement = ({ security, refUuidMap, uuidObjectHashMap, hashedNodeMap, uuid, }) => {
    const securityRequirementObject = {};
    Object.entries(security).forEach(([securitySchemeName, securitySchemeScopes]) => {
        // create security requirement object
        // add $ref to matching security scheme from components.securitySchemes
        // add scopes to the security requirement object
        const schemeName = resolveSecuritySchemeName(securitySchemeName, refUuidMap);
        const refId = schemeName === undefined ? undefined : `${SECURITY_SCHEMES_POINTER}${schemeName}`;
        const refUuid = (refId && refUuidMap[refId]) || uuidv4();
        securityRequirementObject[securitySchemeName] = Object.assign({ $ref: refUuid, scopes: securitySchemeScopes }, (schemeName !== undefined ? { schemeName } : {}));
    });
    const objectHash = hash(securityRequirementObject);
    uuidObjectHashMap[uuid] = objectHash;
    hashedNodeMap[objectHash] = securityRequirementObject;
};
